/* Minicharts examples: one drawing for each of the 54 chart types, each drawn as what it is named after. Generated by hand-diagrams/src/build.py from src/cards-*.js. */

/* r0: small drawing helpers shared by cards-0 and cards-1. Solid fills, plain strokes, ellipses, gradients, soft ground shadows. */
const r0 = {
  I:'#5e5f6b',
  sol:(pts,col,op = 1) => out.push(`<path d="${pathOf(pts)}Z" fill="${col}"${op < 1 ? ` opacity="${op}"` : ''}/>`),
  ln:(pts,col = '#5e5f6b',w = 1,op = 1) => out.push(`<path d="${pathOf(pts)}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"${op < 1 ? ` opacity="${op}"` : ''}/>`),
  el:(cx,cy,rx,ry = rx,n = 32) => Array.from({length:n},(_,i) => { const t = i/n*2*Math.PI; return [cx+rx*Math.cos(t),cy+ry*Math.sin(t)]; }),
  arc:(cx,cy,rx,ry,a0,a1,n = 20) => Array.from({length:n+1},(_,i) => { const t = (a0+(a1-a0)*i/n)*Math.PI/180; return [cx+rx*Math.cos(t),cy+ry*Math.sin(t)]; }),
  part:(pts,col,w = 1,ink = '#5e5f6b') => { r0.sol(pts,col); rim(pts,w,ink); },
  shadow:(cx,cy,rx,ry,op = .13) => r0.sol(r0.el(cx,cy,rx,ry,40),'#5e5f6b',op),
  dot:(x,y,r,col,op = 1) => out.push(`<circle cx="${n1(x)}" cy="${n1(y)}" r="${n1(r)}" fill="${col}"${op < 1 ? ` opacity="${op}"` : ''}/>`),
  stops:s => s.map(([o,c,a = 1]) => `<stop offset="${o}" stop-color="${c}"${a < 1 ? ` stop-opacity="${a}"` : ''}/>`).join(''),
  lg:(id,s,{x1 = 0,y1 = 0,x2 = 1,y2 = 0} = {}) => `<linearGradient id="${id}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}">${r0.stops(s)}</linearGradient>`,
  rg:(id,s,{cx = .5,cy = .5,r = .5,fx = cx,fy = cy} = {}) => `<radialGradient id="${id}" cx="${cx}" cy="${cy}" r="${r}" fx="${fx}" fy="${fy}">${r0.stops(s)}</radialGradient>`,
  defs:(...g) => out.push(`<defs>${g.join('')}</defs>`),
  /* a local frame: a along the angle, b across it */
  frame:(o,ang) => (a,b) => [o[0]+a*Math.cos(ang)-b*Math.sin(ang),o[1]+a*Math.sin(ang)+b*Math.cos(ang)],
};

