card({id:'pyramid',sec:'named',name:'Pyramid',of:'what a cat needs',note:'The wide layers come first. Nobody knocks a cup off a shelf on an empty stomach.',draw(){
  const T = [['knocking things off',"only when all else is sorted"],['a lap','on its own terms'],['a cardboard box','any box, any size'],['a warm spot','sun on the floor will do'],['dinner, on time','the base of everything']];
  OX = 190; OY = 300; const s = 176, H = 220, hz = z => s/2*(1-z/H), TINT = ['#c1a372','#d7b777','#c3ab84','#cca599','#bea7b6'];
  /* shadow to the right, and a bowl of dinner on the floor */
  PT('Its shadow, cool on the floor',() => r3sol([P(s/2,s/2),P(s/2,-s/2),[352,374]],r3I,.1));
  [...T].reverse().forEach(([n,t],k) => { const z0 = k*44, z1 = (k+1)*44, h0 = hz(z0)-(k ? 5 : 0), h1 = k === 4 ? 0 : hz(z1), col = mixC('#d5c098',TINT[k],.45), zm = (z0+z1)/2, hm = (hz(zm)+(k ? hz(zm)-5 : hz(zm)))/2-(k ? 2.5 : 0);
    PT(`${n}: ${t}`,() => {
      const L = [P(-h0,h0,z0),P(h0,h0,z0),P(h1,h1,z1),P(-h1,h1,z1)], R = [P(h0,h0,z0),P(h0,-h0,z0),P(h1,-h1,z1),P(h1,h1,z1)];
      if (k < 4){ const Tp = [P(-h1,-h1,z1),P(h1,-h1,z1),P(h1,h1,z1),P(-h1,h1,z1)]; r3sol(Tp,mixC(col,'#faf2e1',.45)); rim(Tp,.7,trim(col)); }
      r3sol(L,mixC(col,'#faf2e1',.18)); r3sol(R,shadeOf(col));
      /* stone courses and joints, thin and dim */
      const hc = z => Math.max(0,h0+(h1-h0)*(z-z0)/(z1-z0)), J = [];
      if (k < 4){ const zc = (z0+z1)/2, hcm = hc(zc); J.push([P(-hcm,hcm,zc),P(hcm,hcm,zc)],[P(hcm,hcm,zc),P(hcm,-hcm,zc)]);
        const nj = Math.max(1,Math.round(h0/16)); for (let j = 1; j <= nj*2; j++){ const f = j/(nj*2+1), lo = (j%2) ? [z0,zc] : [zc,z1]; for (const [za,zb] of [lo]){ const a = hc(za), b = hc(zb); J.push([P(-a+2*a*f,a,za),P(-b+2*b*f,b,zb)],[P(a,a-2*a*f,za),P(b,b-2*b*f,zb)]); } } }
      rule(J,trim(col),.6,.7); rim(L,1.1,r3I); rim(R,1.1,r3I);
      if (k === 4){ /* the cat on top, and the cup it is about to knock off */
        r3cat(OX-2,OY-H+6,.9); out.push(`<g transform="rotate(38 ${OX+30} ${OY-H+20})">`); propCup(OX+30,OY-H+28,.5); out.push('</g>'); }
      const a = P(hz(zm)-(k ? 5 : 0),0,zm), ty = Math.round(a[1]+5);
      if (k === 4){ lead([370,ty-14],[a[0]-4,a[1]+4],1); TX(378,ty-9,'knocking',{size:15}); TX(378,ty+9,'things off',{size:15}); }
      else { lead([370,ty-6],a,1); TX(378,ty,n,{size:15}); }
    },{lift:[0,-3]}); });
  PT('Dinner, in its bowl, on time',() => { r3shad(74,397,28,5,.14); const b = [...r3el(70,384,24,7,24).slice(0,13),[50,396],[90,396]]; const top = r3el(70,384,24,7,24); r3sol([[46,384],[94,384],[86,398],[54,398]],'#899fb1'); rim([[46,384],[94,384],[86,398],[54,398]],1,r3I); r3pt(top,'#afc0cf',1); r3sol(r3el(70,385,18,4.6,20),'#b89b70'); for (let i = 0; i < 9; i++) r3sol(r3el(58+i*3,383+(i%3),2,1.4,8),'#ac8956'); });
}});
