  const rock = (px,py,r) => { const b = blob(px,py-r*.55,r,r*.62,.1,5); r3shad(px+2,py,r*1.05,2,.14); r3sol(b,'#b9b3a8'); clipped(b,() => r3sol(r3el(px+r*.45,py,r*.9,r*.6),'#9a958b',.55)); rim(b,.9,r3I); r3ln(bend([px-r*.5,py-r*.7],[px-r*.1,py-r*1],[px+r*.3,py-r*.85]),'#e0dcd2',1,.8); };
