    for (const [a,b] of treads) r3ln([[a[0]+1,a[1]+1.8],[b[0]-1,b[1]+1.8]],b[1] < y(700) ? '#f0f3f5' : '#9aad7b',3.4);
    const sn = [[x(7),y(760)],[x(END),y(760)],[x(END),y(760)+10],[x(7.6),y(760)+6],[x(7.3),y(760)+13],[x(7.1),y(760)+7],[x(7),y(760)+11]]; r3sol(sn,'#f4f6f9'); rim(sn,.7,'#bbc6d0');
