/* r4: small drawing helpers for the cards in this file only */
const r4 = (() => {
  const I = '#5e5f6b';
  const sol = (pts,col,op = 1) => out.push(`<path d="${pathOf(pts)}Z" fill="${col}"${op < 1 ? ` opacity="${op}"` : ''}/>`);
  const el = (cx,cy,rx,ry = rx,n = 28) => Array.from({length:n},(_,i) => { const t = i/n*2*Math.PI; return [cx+rx*Math.cos(t),cy+ry*Math.sin(t)]; });
  const arc = (cx,cy,rx,ry,a0,a1,n = 16) => Array.from({length:n+1},(_,i) => { const t = (a0+(a1-a0)*i/n)*Math.PI/180; return [cx+rx*Math.cos(t),cy+ry*Math.sin(t)]; });
  const pt = (pts,col,w = 1,ic = I) => { sol(pts,col); rim(pts,w,ic); };
  const ln = (pts,col = I,w = 1,op = 1,dash) => out.push(`<path d="${pathOf(pts)}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"${op < 1 ? ` opacity="${op}"` : ''}${dash ? ` stroke-dasharray="${dash}"` : ''}/>`);
  const bx = (x,y,w,h) => [[x,y],[x+w,y],[x+w,y+h],[x,y+h]];
  const rot = (deg,cx,cy,fn) => { out.push(`<g transform="rotate(${n1(deg)} ${n1(cx)} ${n1(cy)})">`); fn(); out.push('</g>'); };
  let F = 'r4f';
  const defs = (k,extra = '') => { F = 'r4f-'+k; out.push(`<defs><filter id="${F}" x="-30%" y="-30%" width="160%" height="160%"><feGaussianBlur stdDeviation="2.4"/></filter>${extra}</defs>`); };
  /* a soft shadow: the shape again, dark, blurred and pushed down-right */
  const shade = (pts,dx = 3,dy = 4,op = .18) => out.push(`<path d="${pathOf(pts)}Z" fill="${I}" opacity="${op}" transform="translate(${dx} ${dy})" filter="url(#${F})"/>`);
  /* wood grain: long gentle waves, one path */
  const grain = (x0,y0,x1,y1,gap,col,op = .5,w = .6) => { let d = ''; for (let y = y0+gap/2; y < y1; y += gap){ const ph = rnd()*6, a = .6+rnd()*1.4; let s = ''; for (let x = x0; x <= x1; x += 10) s += (s ? 'L' : 'M')+n1(x)+' '+n1(y+a*Math.sin(x*.016+ph)+.5*Math.sin(x*.06+ph*2)); d += s; } out.push(`<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" opacity="${op}"/>`); };
  /* specks: many tiny round dots in one path */
  const specks = (x0,y0,x1,y1,n,col,w = 1.4,op = .5) => { let d = ''; for (let i = 0; i < n; i++) d += `M${n1(x0+rnd()*(x1-x0))} ${n1(y0+rnd()*(y1-y0))}h.01`; out.push(`<path d="${d}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" opacity="${op}"/>`); };
  /* the same outline moved inwards by d */
  const inset = (pts,d) => { const n = pts.length, area = q => Math.abs(q.reduce((s,p,i) => { const r = q[(i+1)%n]; return s+p[0]*r[1]-r[0]*p[1]; },0)), off = k => pts.map((p,i) => { const a = pts[(i-1+n)%n], b = pts[(i+1)%n], tx = b[0]-a[0], ty = b[1]-a[1], l = Math.hypot(tx,ty)||1; return [p[0]-ty/l*d*k,p[1]+tx/l*d*k]; }); const A = off(1), B = off(-1); return area(A) < area(B) ? A : B; };
  return {I,sol,el,arc,pt,ln,bx,rot,defs,shade,grain,specks,inset};
})();

