/* Architecture drawn as a real building: a corner bakery cut open from cellar to roof. Floors are the layers;
   the hoist, chute, pipe, lift and flue are how the parts talk. */
const zDarchI = '#7b8088';
const zDarchSol = (pts,col,op = 1) => out.push(`<path d="${pathOf(pts)}Z" fill="${col}"${op < 1 ? ` opacity="${op}"` : ''}/>`);
const zDarchLn = (pts,col,w = 1,op = 1) => out.push(`<path d="${pathOf(pts)}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"${op < 1 ? ` opacity="${op}"` : ''}/>`);
const zDarchEl = (cx,cy,rx,ry,n = 24) => Array.from({length:n},(_,i) => { const t = i/n*2*Math.PI; return [cx+rx*Math.cos(t),cy+ry*Math.sin(t)]; });
const zDarchBx = (x,y,w,h) => [[x,y],[x+w,y],[x+w,y+h],[x,y+h]];
const zDarchPt = (pts,col,w = 1) => { flat(pts,col); rim(pts,w,zDarchI); };
/* a flour sack standing on (x,b) */
const zDarchSack = (x,b,w = 22,h = 26) => { const s = spline([[x-w/2,b],[x+w/2,b],[x+w/2+1,b-h*.6],[x+w/2-3,b-h],[x-w/2+3,b-h],[x-w/2-1,b-h*.6]],true,2); flat(s,'#e8e1d3'); zDarchSol(zDarchBx(x-w/2+1,b-h*.55,w-2,3.5),'#a5b7c5'); zDarchLn(bend([x-4,b-h+3],[x,b-h+6],[x+4,b-h+3]),'#b6b0a4',.7); lid(s,1); };
/* a loaf seen side on, sitting on b */
const zDarchLoaf = (x,b,w = 9,c = '#c8ae7e') => { const l = spline([[x-w,b],[x+w,b],[x+w,b-3],[x+w*.6,b-6],[x-w*.6,b-6],[x-w,b-3]],true,2); flat(l,c); zDarchLn([[x-w*.3,b-5],[x,b-3]],'#e7d9bd',.8); rim(l,.6,zDarchI); };

