/* bar: a sweet shop's week of chocolate bar sales, each flavour a real bar standing on the counter, one square per ten sold */
const zAbarI = '#7b8088';
const zAbarSol = (pts,col,op = 1) => out.push(`<path d="${pathOf(pts)}Z" fill="${col}"${op < 1 ? ` opacity="${op}"` : ''}/>`);
const zAbarLn = (pts,col,w = 1,op = 1) => out.push(`<path d="${pathOf(pts)}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"${op < 1 ? ` opacity="${op}"` : ''}/>`);
const zAbarBx = (x,y,w,h) => [[x,y],[x+w,y],[x+w,y+h],[x,y+h]];
const zAbarEl = (cx,cy,rx,ry,n = 24) => Array.from({length:n},(_,i) => { const t = i/n*2*Math.PI; return [cx+rx*Math.cos(t),cy+ry*Math.sin(t)]; });
/* one bar standing on its end: n squares high, two wide, with its thickness showing on the right and top */
const zAbarBar = (X,B,n,c,{nuts = false} = {}) => {
  const sw = 19, sh = 17, L = X-sw, R = X+sw, T = B-n*sh, dx = 6, dy = -4;
  const side = [[R,B],[R+dx,B+dy],[R+dx,T+dy],[R,T]], top = [[L,T],[R,T],[R+dx,T+dy],[L+dx,T+dy]], face = zAbarBx(L,T,2*sw,n*sh);
  flat(side,shadeOf(c)); flat(top,mixC(c,'#f8f3ea',.22)); flat(face,c);
  const hi = mixC(c,'#f8f3ea',.32), lo = mixC(c,TONE,.38), pd = 2.6;
  for (let r = 0; r < n; r++) for (let q = 0; q < 2; q++){ const x0 = L+q*sw+pd, y0 = T+r*sh+pd, x1 = L+(q+1)*sw-pd, y1 = T+(r+1)*sh-pd;
    zAbarSol(zAbarBx(x0,y0,x1-x0,y1-y0),mixC(c,'#f8f3ea',.07));
    zAbarLn([[x0,y1],[x0,y0],[x1,y0]],hi,.7,.9); zAbarLn([[x1,y0],[x1,y1],[x0,y1]],lo,.6,.9);
    if (nuts && (r*3+q*5)%4 !== 1){ const nx = x0+4+((r*7+q*3)%5)*1.6, ny = y0+3.5+((r*5+q)%3)*2.2; zAbarSol(zAbarEl(nx,ny,2.4,1.7,10),'#d0b687'); zAbarLn(zAbarEl(nx,ny,2.4,1.7,10).concat([[nx+2.4,ny]]),lo,.5,.8); } }
  rule([[[X,T+1],[X,B-1]],...Array.from({length:n-1},(_,r) => [[L+1,T+(r+1)*sh],[R-1,T+(r+1)*sh]])],lo,.6,.75);
  zAbarLn([[L+2.2,T+4],[L+2.2,B-10]],'#f7f7f7',1.2,.28);
  lid(face,1.15); zAbarLn([[R,B],[R+dx,B+dy],[R+dx,T+dy],[L+dx,T+dy],[L,T]],zAbarI,1); zAbarLn([[R,T],[R+dx,T+dy]],zAbarI,.7);
  return T+dy; };
/* the foil, peeled down to the bar's foot and splayed out like petals */
