/* Flowchart drawn as water that really flows: a rain butt, a valve that asks the question, pipes with water in them. */
const zBflowI = '#7b8088';
/* a path with its inner corners rounded */
const zBflowElbow = (pts,R = 14) => { const o = [pts[0]]; for (let i = 1; i < pts.length-1; i++) o.push(...round(pts[i-1],pts[i],pts[i+1],R)); o.push(pts.at(-1)); return o; };
/* a clear pipe with water in it */
const zBflowPipe = pts => { r0.ln(pts,zBflowI,11.5); r0.ln(pts,'#e2e8eb',9.2); r0.ln(pts,'#acc0d1',4.6); r0.ln(pts.map(([a,b]) => [a-1.6,b-2.4]),'#f6f9fa',1,.7); };
/* a collar where two lengths of pipe meet */
const zBflowCollar = (x,y,vert) => r0.part(vert ? rrect(x-7.5,y-4,15,8,2) : rrect(x-4,y-7.5,8,15,2),'#b9bfc3',.8);
/* drops of water walking along a pipe */
const zBflowDrops = (pts,n,dur) => { const d = 'M'+pts.map(q => n1(q[0])+' '+n1(q[1])).join('L'); for (let i = 0; i < n; i++) out.push(`<circle r="1.7" fill="#f2f5f8" opacity=".95"><animateMotion dur="${dur}s" begin="-${(i*dur/n).toFixed(2)}s" repeatCount="indefinite" path="${d}" calcMode="paced"/></circle>`); };

