  PT('spare pegs in the grass',() => { for (const [px,py,r] of [[184,380,-30],[198,386,20],[214,378,70]]) r2rot(px,py,r,() => { const p = rrect(px-2.4,py-7,4.8,14,1.6); flat(p,'#ccb68f'); rim(p,.9,zAlineI); zAlineSol(zAlineBx(px-2.6,py-1,5.2,2),'#acb0b4'); }); });
