/* Mind map drawn as a folded paper road map: the town is the idea, roads go to districts, lanes to villages. */
const zDmindI = '#7b8088';
const zDmindSol = (pts,col,op = 1) => out.push(`<path d="${pathOf(pts)}Z" fill="${col}"${op < 1 ? ` opacity="${op}"` : ''}/>`);
const zDmindLn = (pts,col,w = 1,op = 1,da) => out.push(`<path d="${pathOf(pts)}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"${op < 1 ? ` opacity="${op}"` : ''}${da ? ` stroke-dasharray="${da}"` : ''}/>`);
const zDmindEl = (cx,cy,rx,ry,n = 24) => Array.from({length:n},(_,i) => { const t = i/n*2*Math.PI; return [cx+rx*Math.cos(t),cy+ry*Math.sin(t)]; });
const zDmindBx = (x,y,w,h) => [[x,y],[x+w,y],[x+w,y+h],[x,y+h]];
/* a little map tree: a round green crown on a dot of shadow */
const zDmindTree = (x,y,r = 4.2) => { zDmindSol(zDmindEl(x+1,y+1.4,r,r*.8,12),'#92a282',.35); const c = zDmindEl(x,y,r,r,14); flat(c,'#adc098'); rim(c,.55,'#92a282'); };
/* a built-up area: a soft blob with a few house blocks in it */
