/* org: an organ. Each person is a pipe standing on its own wind chest; tubes carry the wind from the head's chest down to the chests of those who report to them. Pipe length is years on the team. */
const zCorgK = 4.5, zCorgFOOT = 16;
/* one tin pipe standing on the chest top at (x, base): a cone foot, a mouth with its lip, a body as long as the years */
const zCorgPipe = (x,base,yrs,w,{red = false} = {}) => {
  const top = base-zCorgFOOT-yrs*zCorgK, m = base-zCorgFOOT, h = w/2;
  r0.sol([[x-h+3,top+4],[x+h+3,top+4],[x+h+3,base],[x-h+3,base]],r0.I,.1);
  const foot = [[x-h,m],[x+h,m],[x+2.6,base],[x-2.6,base]]; r0.sol(foot,'url(#zCorgT)'); rim(foot,1.1,r0.I);
  const body = [[x-h,top],[x+h,top],[x+h,m],[x-h,m]]; r0.sol(body,'url(#zCorgT)');
  r0.ln([[x-h*.45,top+3],[x-h*.45,m-2]],'#f7f8f9',1.4,.7);
  /* the mouth: a dark slot under an arched upper lip */
  const bl = yrs*zCorgK, mh = Math.min(6,Math.max(2.4,bl*.55)), fh = Math.min(mh+3,bl-.5), lip = [[x-h*.55,m],[x-h*.55,m-mh+Math.min(2.4,mh*.4)],...r0.arc(x,m-mh+Math.min(2.4,mh*.4),h*.55,Math.min(2.4,mh*.4),180,360,8),[x+h*.55,m]];
  const fl = [[x-h*.75,m],[x-h*.75,m-fh+Math.min(4,fh*.4)],...r0.arc(x,m-fh+Math.min(4,fh*.4),h*.75,Math.min(4,fh*.4),180,360,8),[x+h*.75,m]]; r0.sol(fl,'#ebedee',.75); rim(fl,.6,mixC('#caced1',TONE,.35));
  r0.sol(lip,'#747a7f'); rim(lip,.7,mixC('#caced1',TONE,.45));
  r0.ln([[x-h*.6,m+.6],[x+h*.6,m+.6]],mixC('#caced1',TONE,.4),.7);
  /* the open top */
  r0.sol(r0.el(x,top,h-.6,1.8,16),red ? RED : '#83888d');
  rim(body,1.15,r0.I); return top; };
/* a wind chest: a wooden box with a brass name plate */
const zCorgChest = (x,y,w,h,name,{sz = 13.5,red = false} = {}) => {
  const c = [[x-w/2,y],[x+w/2,y],[x+w/2,y+h],[x-w/2,y+h]]; r0.sol(c.map(([a,b]) => [a+3,b+4]),r0.I,.14); r0.sol(c,'url(#zCorgW)'); rim(c,1.15,r0.I);
  r0.ln([[x-w/2+2,y+2.5],[x+w/2-2,y+2.5]],'#c1a780',.8,.8);
  const pw = textW(name,sz,true)+16, pl = rrect(x-pw/2,y+h/2-9.5,pw,19,3.5); r0.sol(pl,'url(#zCorgP)'); rim(pl,.9,r0.I);
  for (const sx of [x-pw/2+4.5,x+pw/2-4.5]) r0.dot(sx,y+h/2,1.2,'#a98f5d');
  TX(x,y+h/2+4.8,name,{size:sz,cap:true,anchor:'middle',col:red ? RED : INK}); };
/* a conveyance tube: a lead pipe with rounded bends */
const zCorgTube = pts => { r0.ln(pts,r0.I,5.6); r0.ln(pts,'#acb0b3',3.8); r0.ln(pts.map(([a,b]) => [a-.8,b-.8]),'#dee1e3',1,.8); };
const zCorgBend = (x0,y0,yb,x1,y1,r = 7) => { const s = Math.sign(x1-x0); if (!s) return [[x0,y0],[x0,y1]];
  return [[x0,y0],[x0,yb-r],...bend([x0,yb-r],[x0,yb],[x0+s*r,yb],4).slice(1),[x1-s*r,yb],...bend([x1-s*r,yb],[x1,yb],[x1,yb+r],4).slice(1),[x1,y1]]; };
