/* stacked: a chocolate kitchen's week, each day's bars lying in one stack on the marble, layered by kind; one slab is five bars */
const zAstackedI = '#7b8088';
const zAstackedSol = (pts,col,op = 1) => out.push(`<path d="${pathOf(pts)}Z" fill="${col}"${op < 1 ? ` opacity="${op}"` : ''}/>`);
const zAstackedLn = (pts,col,w = 1,op = 1) => out.push(`<path d="${pathOf(pts)}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"${op < 1 ? ` opacity="${op}"` : ''}/>`);
const zAstackedBx = (x,y,w,h) => [[x,y],[x+w,y],[x+w,y+h],[x,y+h]];
const zAstackedEl = (cx,cy,rx,ry,n = 20) => Array.from({length:n},(_,i) => { const t = i/n*2*Math.PI; return [cx+rx*Math.cos(t),cy+ry*Math.sin(t)]; });
const zAstackedW = 54, zAstackedT = 9, zAstackedDX = 14, zAstackedDY = -9;
/* a run of n bars of one kind lying flat, bottom at y0, each one nudged a little as if stacked by hand;
   the long edge faces us, the short end shows on the right, the top bar shows its squares */
const zAstackedLayer = (L0,y0,n,c,{nuts = false,top = false,seed = 0} = {}) => {
  const W = zAstackedW, t = zAstackedT, dx = zAstackedDX, dy = zAstackedDY, lo = mixC(c,TONE,.38), hi = mixC(c,'#f8f3ea',.3), JIT = [0,2.5,-1.5,1,-2.5,1.5,-.5];
  for (let s = 0; s < n; s++){ const L = L0+JIT[(seed+s)%7], R = L+W, yb = y0-s*t, yt = yb-t, last = top && s === n-1;
    const face = zAstackedBx(L,yt,W,t), side = [[R,yb],[R+dx,yb+dy],[R+dx,yt+dy],[R,yt]], tp = [[L,yt],[R,yt],[R+dx,yt+dy],[L+dx,yt+dy]];
    flat(tp,mixC(c,'#f8f3ea',.12)); flat(side,shadeOf(c)); flat(face,c);
    zAstackedLn([[L+1.5,yt+1.6],[R-1.5,yt+1.6]],hi,.7,.85);
    rule(Array.from({length:5},(_,q) => [[L+(q+1)*W/6,yt+2.8],[L+(q+1)*W/6,yb-1.2]]),lo,.5,.55);
    if (nuts) for (let q = 0; q < 3; q++){ const nx = L+8+(((seed+s)*13+q*19)%40), ny = yt+4.8; zAstackedSol(zAstackedEl(nx,ny,2.3,1.6,10),'#d4bb8d'); }
    if (last){ const at = (u,v) => [L+u*W+v*dx,yt+v*dy];
      rule([...Array.from({length:5},(_,q) => [at((q+1)/6,.08),at((q+1)/6,.92)]),[at(.03,.5),at(.97,.5)]],lo,.6,.8);
      for (let q = 0; q < 6; q++) for (const v of [.25,.75]) zAstackedLn([at(q/6+.03,v+.17),at(q/6+.03,v-.17),at(q/6+.13,v-.17)],hi,.6,.8);
      if (nuts) for (const [u,v] of [[.1,.3],[.4,.7],[.75,.25],[.6,.6]]){ const p = at(u,v); zAstackedSol(zAstackedEl(p[0],p[1],2.4,1.5,10),'#d4bb8d'); } }
    lid([[L,yb],[L,yt],[L+dx,yt+dy],[R+dx,yt+dy],[R+dx,yb+dy],[R,yb]],1.1); zAstackedLn([[L,yt],[R,yt],[R+dx,yt+dy]],zAstackedI,.7); zAstackedLn([[R,yt],[R,yb]],zAstackedI,.7); }
  return y0-n*t; };

